import { NextResponse } from "next/server";
import { z } from "zod";
import { isAdmin } from "@/lib/admin";
import { prisma } from "@/lib/db";
import { existsObject } from "@/lib/s3";

const Body = z.object({
  pdfId: z.string().min(1),
});

export async function POST(req: Request) {
  // ✅ Next 16: isAdmin is async
  if (!(await isAdmin())) {
    return NextResponse.json({ error: "Admin only" }, { status: 403 });
  }

  const json = await req.json().catch(() => null);
  const parsed = Body.safeParse(json);

  if (!parsed.success) {
    return NextResponse.json({ error: "Invalid payload" }, { status: 400 });
  }

  const pdf = await prisma.pdf.findUnique({
    where: { id: parsed.data.pdfId },
  });

  if (!pdf) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }

  console.log("FINALIZE checking:", pdf.storageKey, "bucket:", process.env.S3_BUCKET);
  const head = await existsObject(pdf.storageKey);

  if (!head.ok) {
    await prisma.pdf.delete({ where: { id: pdf.id } }).catch(() => {});
    return NextResponse.json(
      {
        error: "S3 verify failed; DB row removed.",
        storageKey: pdf.storageKey,
        bucket: process.env.S3_BUCKET,
        s3: head,
      },
      { status: 409 }
    );
  }

  return NextResponse.json({ ok: true });
}
